mapper.select:
SELECT e.aggregator_id, e.ent_id, e.ent_name, e.percent, e.agreement, d.device_name, d.power,
d.resource_type_id, e.sn_code, t.name AS resourceTypeName
FROM aggregator_ent e, aggregator_ent_device d, aggregator_resource_type t

    e.ent_id = d.ent_id AND d.resource_type_id = t.id

        AND e.aggregator_id = #{aggregatorId}


        AND e.ent_id = #{entId}


        AND d.power >= #{powerGetterThan}


        AND d.power <= #{powerLessThan}


        AND e.percent = #{percent}


ORDER BY t.resource_order, d.id

SELECT e.aggregator_id, e.ent_id, e.station_id, e.ent_name, e.agreement, e.service_start_date, e.service_end_date, CONCAT_WS('~', DATE_FORMAT(e.service_start_date,'%Y/%m/%d'), DATE_FORMAT(e.service_end_date,'%Y/%m/%d')) AS agreementDate, d.device_base_id, d.ent_id, d.device_id, d.account_no, d.device_name, d.power, d.max_power, d.response_power, s.name AS smsName, s.phone AS smsPhone FROM aggregator_ent e LEFT JOIN aggregator_ent_device d ON e.ent_id = d.ent_id AND d.del_flag = 1 LEFT JOIN aggregator_sms s ON e.ent_id = s.ent_id AND s.query_flag = 1
AND e.ent_id = #{entId}
AND
YEAR(e.service_start_date) <= #{year} AND YEAR(e.service_end_date) >= #{year}
ORDER BY e.id, d.id

