mapper.update:
UPDATE aggregator_ent
SET agreement = null
WHERE ent_id = #{entId}

UPDATE aggregator_ent
SET agreement          = #{agreement},
    service_start_date = #{serviceStartDate},
    service_end_date   = #{serviceEndDate},
    `percent` = #{percent}
WHERE ent_id = #{entId}
